/**
 * What the body editor knows about a request body, from Okta's OpenAPI spec
 * (generated by `npm run bodies`): its fields, for completions as keys and values
 * are typed and for descriptions on hover; problems to underline (missing
 * required fields, unknown ones, wrong types and values); and the spec's examples.
 * Each API area's bodies are a separate file, loaded only when the Body tab asks
 * for one of its endpoints.
 */
import { cursorAt, joinPath, parentOf, parseJson, type JsonNode } from './jsonDoc';
import type { Endpoint } from './suggest';

export interface BodyField {
  /** Dotted path; `[]` steps into an array's items, e.g. `groupIds`, `roles[].type`. */
  p: string;
  /** JSON type, `[]` for arrays, e.g. `string`, `object`, `string[]`. */
  t: string;
  /** Required (when its parent object is there). */
  r?: 1;
  /** Short description. */
  d?: string;
  /** Allowed values. */
  e?: string[];
  /** Allowed values beyond those in `e`. */
  m?: 1;
  /** An object (or array of them) that takes fields besides those listed. */
  a?: 1;
}

export interface BodyExample {
  n: string;
  v: unknown;
}

export interface BodySchema {
  f: BodyField[];
  x?: BodyExample[];
  /** The body takes fields besides those listed. */
  a?: 1;
}

type Chunk = Record<string, BodySchema>;

const chunks = import.meta.glob<Chunk>('./bodies/*.json', { import: 'default' });
const loading = new Map<string, Promise<Chunk | undefined>>();

const chunkName = (tag: string) => `./bodies/${tag.replace(/[^\w-]/g, '_')}.json`;

/** The body schema of `endpoint`, or undefined if the spec gives it no JSON body. */
export async function loadBodySchema(endpoint: Endpoint): Promise<BodySchema | undefined> {
  const name = chunkName(endpoint.t);
  let chunk = loading.get(name);
  if (!chunk) {
    const load = chunks[name];
    chunk = load ? load().catch(() => undefined) : Promise.resolve(undefined);
    loading.set(name, chunk);
  }
  return (await chunk)?.[`${endpoint.m} ${endpoint.p}`];
}

const fieldMap = new WeakMap<BodySchema, Map<string, BodyField>>();
/** `schema`'s fields by path. */
function fieldsOf(schema: BodySchema) {
  let map = fieldMap.get(schema);
  if (!map) fieldMap.set(schema, (map = new Map(schema.f.map((f) => [f.p, f]))));
  return map;
}

/** The fields directly under `path` (an object's, or `roles[]` for an array's items). */
const childrenOf = (schema: BodySchema, path: string) =>
  schema.f.filter((f) => parentOf(f.p) === path);

/** The array field whose items `path` is, e.g. `roles` for `roles[]`. */
const arrayField = (schema: BodySchema, path: string) =>
  path.endsWith('[]') ? fieldsOf(schema).get(path.slice(0, -2)) : undefined;

// --- Completions ---------------------------------------------------------------

export interface BodyCompletion {
  label: string;
  /** Replaces the token being typed. `${…}` marks where the cursor goes (a CodeMirror snippet). */
  snippet: string;
  detail?: string;
  info?: string;
  required?: boolean;
  /** How it's shown, if not as `label` (which is matched against what's typed). */
  display?: string;
  kind: 'property' | 'enum' | 'keyword';
}

const describe = (field: BodyField) =>
  [field.d, field.e && `One of: ${field.e.join(', ')}${field.m ? ', …' : ''}`]
    .filter(Boolean)
    .join('\n\n') || undefined;

/** The value a key's completion starts it with. */
function valueSnippet(field: BodyField) {
  if (field.t.endsWith('[]')) return '[${}]';
  if (field.e?.length && field.t === 'string') return `"\${${field.e[0]}}"`;
  switch (field.t) {
    case 'object':
      return '{\n\t${}\n}';
    case 'string':
      return '"${}"';
    case 'integer':
    case 'number':
      return '${0}';
    case 'boolean':
      return '${false}';
    default:
      return '${}';
  }
}

const quote = (value: string) => JSON.stringify(value);

export interface CompletionList {
  /** The token being typed, its opening quote included, to replace. */
  from: number;
  to: number;
  options: BodyCompletion[];
  /** A key or value is being typed (rather than the cursor resting in whitespace). */
  typing: boolean;
  /** Typed after a quote: match the options against what follows it. */
  quoted: boolean;
}

/**
 * What can go at `pos`: an object's other keys (required ones first), or the
 * allowed values of the key or array it's in.
 */
export function completionsAt(
  text: string,
  pos: number,
  schema: BodySchema,
): CompletionList | undefined {
  const cursor = cursorAt(text, pos);
  if (!cursor) return undefined;
  // A quote the editor closed for us goes too.
  const to = cursor.quoted && text[pos] === '"' ? pos + 1 : pos;
  const typing = cursor.quoted || cursor.prefix !== '';
  const result = (options: BodyCompletion[]) =>
    options.length ? { from: cursor.from, to, options, typing, quoted: cursor.quoted } : undefined;

  if (cursor.slot === 'key') {
    const present = new Set(cursor.keys);
    return result(
      childrenOf(schema, cursor.path)
        .filter((f) => !present.has(f.p.slice(cursor.path.length + (cursor.path ? 1 : 0))))
        .map((field) => {
          const name = field.p.slice(field.p.lastIndexOf('.') + 1);
          return {
            label: name,
            snippet: `${quote(name)}: ${valueSnippet(field)}`,
            detail: field.t,
            info: describe(field),
            required: !!field.r,
            kind: 'property' as const,
          };
        })
        .sort((a, b) => Number(b.required) - Number(a.required)),
    );
  }

  const field =
    cursor.slot === 'value'
      ? fieldsOf(schema).get(joinPath(cursor.path, cursor.key ?? ''))
      : arrayField(schema, cursor.path);
  if (!field) return undefined;
  const type = field.t.replace(/\[\]$/, '');
  if (field.e?.length) {
    return result(
      field.e.map((value) => ({
        label: value,
        display: quote(value),
        snippet: quote(value),
        detail: field.p,
        kind: 'enum' as const,
      })),
    );
  }
  if (type === 'boolean') {
    return result(
      ['true', 'false'].map((value) => ({
        label: value,
        snippet: value,
        kind: 'keyword' as const,
      })),
    );
  }
  return undefined;
}

/** The field a key at `path` is, for its description on hover. */
export const fieldAt = (schema: BodySchema, path: string) => fieldsOf(schema).get(path);

export const fieldInfo = (field: BodyField) => describe(field);

// --- Problems ------------------------------------------------------------------

export interface BodyProblem {
  from: number;
  to: number;
  severity: 'error' | 'warning';
  message: string;
}

const kindName = (node: JsonNode) =>
  node.kind === 'number' && Number.isInteger(node.value) ? 'an integer' : `a ${node.kind}`;

/** Does `node` have JSON type `type` (`string`, `integer`, `object`…)? Null passes. */
function hasType(node: JsonNode, type: string) {
  if (node.kind === 'null' || type === 'any') return true;
  if (type.endsWith('[]')) return node.kind === 'array';
  if (type === 'integer') return node.kind === 'number' && Number.isInteger(node.value);
  return node.kind === type;
}

/**
 * Problems with a body (that is valid JSON) against its schema: required fields
 * it's missing, fields the spec doesn't list, and values of the wrong type or not
 * among those allowed.
 */
export function lintBody(text: string, schema: BodySchema): BodyProblem[] {
  const root = parseJson(text);
  if (!root) return [];
  const problems: BodyProblem[] = [];
  const fields = fieldsOf(schema);

  /** A value, as `field` (or the item of `field`, when `item`). */
  const checkValue = (node: JsonNode, field: BodyField, item = false) => {
    const type = item ? field.t.replace(/\[\]$/, '') : field.t;
    if (!hasType(node, type)) {
      const expected = type.endsWith('[]')
        ? 'an array'
        : `a${/^[aeiou]/.test(type) ? 'n' : ''} ${type}`;
      problems.push({
        from: node.from,
        to: node.to,
        severity: 'warning',
        message: `${field.p}${item ? ' items' : ''} should be ${expected}, not ${kindName(node)}.`,
      });
      return;
    }
    const scalar = item || !field.t.endsWith('[]');
    if (scalar && field.e?.length && !field.m && node.kind === 'string') {
      if (!field.e.includes(node.value as string)) {
        problems.push({
          from: node.from,
          to: node.to,
          severity: 'warning',
          message: `${quote(node.value as string)} isn't an allowed ${field.p}: ${field.e.join(', ')}.`,
        });
      }
    }
  };

  /** An object or array at `path`, `anchor` being where to report fields it's missing. */
  const walk = (node: JsonNode, path: string, anchor: { from: number; to: number }) => {
    if (node.kind === 'array') {
      const field = fields.get(path);
      for (const item of node.items) {
        if (field) checkValue(item, field, true);
        walk(item, `${path}[]`, { from: item.from, to: item.from + 1 });
      }
      return;
    }
    if (node.kind !== 'object') return;
    const known = childrenOf(schema, path);
    if (!known.length) return;
    const owner = path === '' ? schema : (fields.get(path) ?? arrayField(schema, path));
    const closed = !owner?.a;
    const keys = new Set(node.props.map((p) => p.key));

    const missing = known.filter((f) => f.r && !keys.has(f.p.slice(f.p.lastIndexOf('.') + 1)));
    if (missing.length) {
      const names = missing.map((f) => f.p.slice(f.p.lastIndexOf('.') + 1));
      problems.push({
        ...anchor,
        severity: 'error',
        message: `Missing required field${names.length > 1 ? 's' : ''}${path ? ` in ${path}` : ''}: ${names.join(', ')}.`,
      });
    }

    for (const prop of node.props) {
      const childPath = joinPath(path, prop.key);
      const field = fields.get(childPath);
      const keyRange = { from: prop.keyFrom, to: prop.keyTo };
      if (!field) {
        if (closed) {
          problems.push({
            ...keyRange,
            severity: 'warning',
            message: `Unknown field ${quote(prop.key)}${path ? ` in ${path}` : ''}.`,
          });
        }
        continue;
      }
      checkValue(prop.value, field);
      walk(prop.value, childPath, keyRange);
    }
  };

  walk(root, '', { from: root.from, to: root.from + 1 });
  return problems.sort((a, b) => a.from - b.from);
}

// --- Examples ------------------------------------------------------------------

const isObject = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

const placeholder = (field: BodyField): unknown => {
  if (field.t.endsWith('[]')) return [];
  if (field.e?.length) return field.e[0];
  switch (field.t) {
    case 'object':
      return {};
    case 'integer':
    case 'number':
      return 0;
    case 'boolean':
      return false;
    default:
      return '';
  }
};

/**
 * A starter body when the spec has no examples: each required field (and the
 * required fields of required objects) with a placeholder value.
 */
export function skeleton(fields: BodyField[]): Record<string, unknown> {
  const body: Record<string, unknown> = {};
  const byPath = new Map(fields.map((f) => [f.p, f]));
  for (const field of fields) {
    if (!field.r || field.p.includes('[]')) continue;
    const steps = field.p.split('.');
    // Every object above it must be required too.
    const chain = steps.map((_, i) => byPath.get(steps.slice(0, i + 1).join('.')));
    if (chain.some((f) => !f?.r)) continue;
    let target = body;
    for (const step of steps.slice(0, -1)) {
      const next = target[step];
      if (!isObject(next)) target[step] = {};
      target = target[step] as Record<string, unknown>;
    }
    const key = steps[steps.length - 1]!;
    if (!(key in target)) target[key] = placeholder(field);
  }
  return body;
}

/** The body to insert for an example (or the skeleton), as formatted JSON. */
export const exampleBody = (value: unknown) => JSON.stringify(value, null, 2);
